private boolean isOptionActive(String action) {
    if (action == null || action.isBlank()) {
        return false;
    }
    String[] parts = action.split(":", 3);
    try {
        if (parts.length == 3 && "field".equals(parts[0])) {
            return switch (PackEntityPresetField.valueOf(parts[1])) {
                case PackEntityPresetField.CATEGORY -> this.allMatch(entry -> entry.categoryOverride().name().equals(parts[2]));
                case PackEntityPresetField.MOVEMENT -> this.allMatch(entry -> entry.movementOverride().name().equals(parts[2]));
                case PackEntityPresetField.BINDING_REQUIREMENT -> this.allMatch(entry -> entry.bindingRequirement().name().equals(parts[2]));
                case PackEntityPresetField.MOUNT_INTERACTION -> this.allMatch(entry -> entry.mountInteractionPolicy().name().equals(parts[2]));
                case PackEntityPresetField.BINDING_ANIMATION -> this.allMatch(entry -> entry.bindingAnimationPolicy().name().equals(parts[2]));
                case PackEntityPresetField.RESCUE_MOTION -> this.allMatch(entry -> entry.rescueMotion().name().equals(parts[2]));
                default -> false;
            };
        }
        if (parts.length == 3 && "style".equals(parts[0])) {
            CompanionEffectPurpose purpose = CompanionEffectPurpose.valueOf(parts[1]);
            CompanionEffectStyle style = CompanionEffectStyle.valueOf(parts[2]);
            return this.allMatch(entry -> switch (purpose) {
                default -> throw new IncompatibleClassChangeError();
                case CompanionEffectPurpose.SUMMON -> {
                    if (entry.summonStyle() == style) {
                        yield true;
                    }
                    yield false;
                }
                case CompanionEffectPurpose.RESCUE -> {
                    if (entry.rescueStyle() == style) {
                        yield true;
                    }
                    yield false;
                }
                case CompanionEffectPurpose.STORAGE -> entry.storageStyle() == style;
            });
        }
        if (parts.length == 3 && "animation".equals(parts[0])) {
            CompanionAnimationPurpose purpose = CompanionAnimationPurpose.valueOf(parts[1]);
            CompanionAnimationStyle style = CompanionAnimationStyle.valueOf(parts[2]);
            return this.allMatch(entry -> FindMeAuiPackEditorScreen.animation(entry, purpose) == style);
        }
    }
    catch (IllegalArgumentException illegalArgumentException) {
        // empty catch block
    }
    return false;
}

