private static boolean replaceContents(Document document, String id, Supplier<String> markup) {
    if (id == null) {
        return false;
    }
    Element element = document.getElementById(id);
    if (element == null) {
        return false;
    }
    element.setInnerHTML(markup.get());
    return true;
