    private void refreshParts(boolean topbar, boolean sidebar, boolean entryPanel, boolean inspector, boolean overlay) {
        Document document = this.getLinkedDocument();
        if (!this.shellBuilt || document == null || document.body == null) {
            this.refreshAll();
            return;
