        if (changed |= FindMeAuiPackEditorScreen.replaceContents(document, inspector ? "pack-inspector" : null, this::inspectorMarkup)) {
            document.rebuildSelectorIndex();
            document.reapplyStylesFromCache();
            this.bind();
            if (inspector) {
                this.restoreFieldsScroll(document);
            }
            this.updateFieldsScrollThumb();
        }
    }

