package com.kuzhi.findme.client;

import com.kuzhi.findme.FindMeMod;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

final class FindMeAuiPerformanceMonitor {
    private static final long REPORT_INTERVAL_NANOS = 10000000000L;
    private static final long WARNING_INTERVAL_NANOS = 2000000000L;
    private static final Map<String, Sample> SAMPLES = new LinkedHashMap<String, Sample>();
    private static final Map<String, Long> LAST_WARNINGS = new LinkedHashMap<String, Long>();
    private static long windowStartedAt = System.nanoTime();

    private FindMeAuiPerformanceMonitor() {
    }

    static long start() {
        return System.nanoTime();
    }

    static void record(Object screen, String phase, long startedAt, double warningMs) {
        long elapsed = Math.max(0L, System.nanoTime() - startedAt);
        String key = screen.getClass().getSimpleName() + "." + phase;
        Sample sample = SAMPLES.computeIfAbsent(key, ignored -> new Sample());
        sample.total += elapsed;
        sample.max = Math.max(sample.max, elapsed);
        ++sample.calls;
        if ((double)elapsed >= warningMs * 1000000.0) {
            long now = System.nanoTime();
            long previous = LAST_WARNINGS.getOrDefault(key, Long.MIN_VALUE);
            if (previous == Long.MIN_VALUE || now - previous >= 2000000000L) {
                LAST_WARNINGS.put(key, now);
                FindMeMod.LOGGER.warn("[FindMe AUI perf] slow phase={} elapsedMs={}", (Object)key, (Object)FindMeAuiPerformanceMonitor.ms(elapsed));
            }
        }
        FindMeAuiPerformanceMonitor.reportIfDue();
    }

    private static void reportIfDue() {
        long now = System.nanoTime();
        if (now - windowStartedAt < 10000000000L || SAMPLES.isEmpty()) {
            return;
        }
        StringBuilder summary = new StringBuilder(512);
        for (Map.Entry<String, Sample> entry : SAMPLES.entrySet()) {
            if (!summary.isEmpty()) {
                summary.append(',');
            }
            Sample sample = entry.getValue();
            summary.append(entry.getKey()).append("(avg/max=").append(FindMeAuiPerformanceMonitor.ms(sample.total / Math.max(1L, sample.calls))).append('/').append(FindMeAuiPerformanceMonitor.ms(sample.max)).append("ms,calls=").append(sample.calls).append(')');
        }
        FindMeMod.LOGGER.info("[FindMe AUI perf] 10s summary phases={}", (Object)summary);
        SAMPLES.clear();
        windowStartedAt = now;
    }

    private static String ms(long nanos) {
        return String.format(Locale.ROOT, "%.3f", (double)nanos / 1000000.0);
    }

    private static final class Sample {
        private long total;
        private long max;
        private long calls;

        private Sample() {
        }
    }
}

