package com.kuzhi.findme.client;

final class FindMeAuiTransitionController {
    private static final long OPEN_NANOS = 380000000L;
    private static final long FOLD_IN_NANOS = 145000000L;
    private static final long FOLD_OUT_NANOS = 380000000L;
    private Phase phase = Phase.IDLE;
    private long phaseStartedAt;
    private long generation;
    private Runnable foldedAction;
    private boolean unfoldAfterAction;

    FindMeAuiTransitionController() {
    }

    void enter(Host host) {
        if (host == null) {
            return;
        }
        ++this.generation;
        this.foldedAction = null;
        this.unfoldAfterAction = false;
        this.phase = Phase.OPENING;
        this.phaseStartedAt = System.nanoTime();
        host.setInputBlocked(true);
        host.beginFoldOut();
    }

    boolean start(Host host, Runnable action, boolean unfoldAfterAction) {
        if (host == null || action == null || this.phase != Phase.IDLE) {
            return false;
        }
        ++this.generation;
        this.foldedAction = action;
        this.unfoldAfterAction = unfoldAfterAction;
        this.phase = Phase.FOLDING_IN;
        this.phaseStartedAt = System.nanoTime();
        host.setInputBlocked(true);
        host.beginFoldIn();
        return true;
    }

    void update(Host host) {
        long duration;
        if (host == null || this.phase == Phase.IDLE) {
            return;
        }
        long activeGeneration = this.generation;
        long elapsed = Math.max(0L, System.nanoTime() - this.phaseStartedAt);
        if (this.phase == Phase.FOLDING_IN && elapsed >= 145000000L) {
            Runnable action = this.foldedAction;
            this.foldedAction = null;
            try {
                if (this.unfoldAfterAction) {
                    this.phase = Phase.FOLDING_OUT;
                    this.phaseStartedAt = System.nanoTime();
                    action.run();
                    if (this.generation == activeGeneration) {
                        host.beginFoldOut();
                    }
                } else {
                    this.phase = Phase.IDLE;
                    action.run();
                }
            }
            catch (Error | RuntimeException failure) {
                this.forceSettle(host);
                throw failure;
            }
